import {spawnSync} from 'node:child_process';
import {localEnvironment} from './local-transport.mjs';
/** Only the read-only lock probe may be repeated; valid ownership failures are final. */
export function readLocalLock(c,{run=spawnSync,timeoutMs=25000,maxAttempts=2}={}){
 const attempts=[];
 for(let i=0;i<Math.min(2,maxAttempts);i++){
  const started=Date.now();
  const r=c.transport==='local'?run(c.phone_controller,['--profile',c.profile,'lock-status'],{encoding:'utf8',timeout:Math.min(25000,timeoutMs),env:localEnvironment(c)}):run('ssh',['-o','BatchMode=yes','-o','ControlMaster=no','-o','ControlPath=none','-o','ConnectTimeout=8','-J',c.ssh_jump,c.host,c.phone_controller+' --profile '+c.profile+' lock-status'],{encoding:'utf8',timeout:Math.min(25000,timeoutMs)});
  const fields=Object.fromEntries([...(r.stdout??'').matchAll(/(\w+)=([^\s]+)/g)].map(m=>[m[1],m[2]]));
  const valid=r.status===0&&!r.error&&(fields.lock==='free'||fields.lock==='held'&&Boolean(fields.owner)&&['true','false'].includes(fields.stale));
  attempts.push({exit_code:r.status??null,signal:r.signal??null,error:r.error?.code??null,stderr:(r.stderr??'').slice(0,1000),elapsed_ms:Date.now()-started,valid});
  if(valid)return {valid:true,fields,attempts};
 }
 return {valid:false,fields:{},attempts};
}

