 need(r.get('state')=='terminal' and isinstance(r.get('started_at'),(int,float)) and isinstance(r.get('ended_at'),(int,float)),'RECEIPT_TIME_MISSING')
 iso=lambda n:datetime.datetime.fromtimestamp(n,datetime.timezone.utc).isoformat()
 e={**{k:t[k] for k in ['task_id','run_id','run_tag']},**{k:c[k] for k in ['profile','serial']},'started_at':iso(r['started_at']),'finished_at':iso(r['ended_at']),'args':b['args'],'response':r['result'],'source_receipt':a}
 d=P/'outreach-envelopes';d.mkdir(mode=0o700,exist_ok=True);dest=d/(p.stem+'-'+field+'.json');durable(dest,e);return asset(dest)
