const broker=String.raw`
import os,sys,fcntl,stat,json
p=sys.argv[1]
fd=os.open(p,os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600)
s=os.fstat(fd)
if not stat.S_ISREG(s.st_mode) or s.st_uid!=os.getuid() or stat.S_IMODE(s.st_mode)!=0o600:sys.exit(14)
try:fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
except BlockingIOError:sys.exit(15)
os.ftruncate(fd,0);os.write(fd,json.dumps({'broker_pid':os.getpid(),'parent_pid':os.getppid()}).encode());os.fsync(fd)
print('READY',flush=True)
sys.stdin.buffer.read()
fcntl.flock(fd,fcntl.LOCK_UN);os.close(fd)
