  let child,timer,out='',settled=false;
  const finish=(error,value)=>{
   if(settled)return;settled=true;clearTimeout(timer);
   // Only this spawned read-only SSH is owned here; never signal a shared master.
   if(error){try{child?.kill('SIGKILL');}catch{}try{child?.unref();}catch{}}
   // Proxy/descendant-held pipes must not keep this Node operation alive after failure.
   for(const stream of [child?.stdin,child?.stdout,child?.stderr])try{stream?.destroy();}catch{}
   if(error)reject(error);else resolve(value);
  };
