  catch{return finish(Error('M4_READ_FAILED'));}
  timer=setTimeout(()=>finish(Error('M4_READ_TIMEOUT')),timeoutMs);
  child.stdout.on('data',b=>{out+=b;});child.stderr.on('data',()=>{});
  for(const stream of [child.stdin,child.stdout,child.stderr])stream.on('error',()=>finish(Error('M4_READ_FAILED')));
