 const authorize=async op=>{
  const deadline=['readback','write_back'].includes(op)?c.cleanup_deadline_ms||c.business_deadline_ms:c.business_deadline_ms;need(Date.now()<deadline,'ACTIVITY_DEADLINE');
  const auth=jsonAsset(authAsset);need(auth.root_task_id===c.root_task_id&&hash(auth.message)===auth.message_sha256&&auth.company_policy_changed===false&&auth.requires_current_pause_and_daily_count_readback===true,'AUTHORIZATION_SCOPE');
  for(const id of [c.root_task_id,task.task_id]){const b=await brain('/tasks/'+encodeURIComponent(id)),t=b.task||b;need(t.id===id&&t.status==='in_progress'&&t.claimed_by===c.actor,'TASK_AUTHORITY_CHANGED');}
  return auth;
 };
 const qualify=async()=>{
  const db=await pool.connect();try{
   await db.query('BEGIN READ ONLY');await db.query("SET LOCAL statement_timeout='10000ms'");need((await db.query('SELECT current_database() AS db')).rows[0]?.db==='zenithjoy','WRONG_DATABASE');
   const profiles=(await db.query('SELECT company_id,tenant_id,config_status,config_version,runtime_config FROM zenithjoy.tenant_company_profiles WHERE company_id=$1',[c.company_id])).rows;const p=profiles[0];
   need(profiles.length===1&&p.tenant_id===c.tenant_id&&p.config_status==='enabled'&&Number(p.config_version)===c.verification.policy_version&&p.runtime_config?.policy_id===c.verification.policy_id,'LIVE_POLICY_CHANGED');
   const accounts=p.runtime_config.platform_accounts.filter(a=>a.profile===c.profile&&a.enabled===true);need(accounts.length===1,'SENDER_AMBIGUOUS');const a=accounts[0];need(a.company_id===c.company_id&&a.tenant_id===c.tenant_id&&a.verification_status==='verified'&&a.device_serial===c.serial&&a.douyin_id===c.sender_id,'SENDER_BINDING_CHANGED');
   const rows=(await db.query("SELECT * FROM zenithjoy.leadgen_bridge_outbox WHERE line_key=$1 AND comment_id=$2 AND feishu_record_id=$3 AND state='confirmed' AND qualification_status='passed'",[c.line,s.comment_id,s.record_id])).rows;need(rows.length===1,'OUTBOX_NOT_UNIQUE');outbox=rows[0];
   const binding=await company.readCollectionAccountBinding(db,{lineKey:c.line,run:outbox.payload.comment_run,sourceRun:outbox.payload.recipient_evidence.scope.source_run});const intent=bridge.nativeIntent(outbox,{companyBinding:binding});
   need(intent.target_douyin_id===s.target_douyin_id&&intent.profile_url===s.profile_url&&intent.comment_id===s.comment_id&&intent.lead_id===s.lead_id&&intent.scoring_run===s.source_103_run&&intent.comment_run===s.source_102_run,'OUTBOX_SCOPE_CHANGED');
   need(intent.qualification.company_id===c.company_id&&intent.qualification.tenant_id===c.tenant_id&&Number(intent.qualification.company_version)===c.verification.policy_version,'OUTBOX_POLICY_CHANGED');
   const comments=(await db.query('SELECT * FROM zenithjoy.leadgen_comments WHERE id=$1 AND line_key=$2',[s.comment_id,c.line])).rows;need(comments.length===1,'COMMENT_NOT_UNIQUE');const comment=comments[0];
   const frozen=(await db.query('SELECT snapshot FROM zenithjoy.company_config_runs WHERE company_id=$1 AND run_id=$2',[c.company_id,comment.judgment_config?.run_id])).rows;need(frozen.length===1&&frozen[0].snapshot.version===c.verification.policy_version,'SCORE_POLICY_CHANGED');
   const result=await score.verifyStoredScore(comment,frozen[0].snapshot);need(result.status==='pass','STORED_SCORE_UNVERIFIED');await db.query('ROLLBACK');
   return {verified:true,company_id:c.company_id,tenant_id:c.tenant_id,policy_version:p.config_version,outbox_id:outbox.id,record_id:s.record_id,comment_id:s.comment_id,model_call_count:0};
  }catch(e){await db.query('ROLLBACK').catch(()=>{});throw e;}finally{db.release();}
 };
 const api=await orders.orderClient(route,{env:process.env,deadlineAt:c.cleanup_deadline_ms||c.business_deadline_ms});
 return {authorize,qualify,api,withLock:fn=>orders.withOrderLock(c.line,fn,{directory:LOCK_DIR}),validateOriginal:r=>bridge.fieldsMatch(outbox,r)&&lib.classifyPending(r.fields)==='ok'&&lib.gradeAllowed(lib.leadGrade(r.fields),route.outreachGrades),
  validateStable:r=>outbox?.fields&&Object.entries(outbox.fields).filter(([k])=>!['状态','发送状态'].includes(k)).every(([k,v])=>txt(r.fields?.[k])===String(v)),
  freshRuntime:async all=>{
   const raw=await sshRead(c),locks=await brain('/device-locks'),lease=(locks.locks||locks).find(l=>l.device_name===c.serial);
   raw.central_lease_valid=lease?.locked_by===c.central_owner&&Date.parse(lease.expires_at)>Date.now()+360000;raw.local_lock_valid=raw.local_owner===c.local_owner;
   const senderMatches=v=>v===c.sender_id||v===`${c.profile}(${c.sender_id})`||v.includes('('+c.sender_id+')');
   raw.today_sent_orders=all.filter(r=>senderMatches(txt(r.fields?.['实际分发号']))&&contactDay(r.fields?.['触达时间'])===raw.date&&(txt(r.fields?.['发送状态'])==='已发送'||txt(r.fields?.['状态'])==='已触达'||/^\[104 sent:/.test(txt(r.fields?.['回复结果'])))).length;
   raw.today_ambiguous_sender_orders=all.filter(r=>txt(r.fields?.['实际分发号'])===c.profile&&contactDay(r.fields?.['触达时间'])===raw.date).length;
   raw.instrumented_today_dm_attempts=raw.today_dm_attempts;if(Number.isSafeInteger(raw.legacy_daily_count))raw.today_dm_attempts=Math.max(raw.today_dm_attempts,raw.legacy_daily_count);
   raw.verified=raw.today_ambiguous_sender_orders===0&&(!raw.legacy_daily_count_file_exists||Number.isSafeInteger(raw.legacy_daily_count))&&raw.state_directory_exists&&raw.ledger_base_exists&&raw.profile_ledger_directory_exists&&raw.unparsed_ledger_rows===0&&raw.local_lock_valid&&raw.central_lease_valid;return raw;
  },checkPreflight:(e,scope)=>checkPreflight(e,scope),checkNative:(e,scope,auth,dir)=>checkNative(e,scope,auth,dir,c),close:()=>pool.end()};
}

