import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
export const hash=v=>crypto.createHash('sha256').update(v).digest('hex');
export const canonical=v=>JSON.stringify(v,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a.localeCompare(b))):x);
export function need(v,code){if(!v)throw Error(code);}
export const txt=v=>Array.isArray(v)?v.map(x=>x.text||'').join(''):(v?.name??String(v??''));
export function save(file,value){const tmp=file+'.'+crypto.randomUUID()+'.tmp';const fd=fs.openSync(tmp,'wx',0o600);try{fs.writeFileSync(fd,JSON.stringify(value,null,2)+'\n');fs.fsyncSync(fd);}finally{fs.closeSync(fd);}fs.renameSync(tmp,file);const d=fs.openSync(path.dirname(file),'r');try{fs.fsyncSync(d);}finally{fs.closeSync(d);}}
export function asset(file){return {path:file,sha256:hash(fs.readFileSync(file))};}
export function readAsset(a){need(a&&path.isAbsolute(a.path),'ASSET_INVALID');const st=fs.lstatSync(a.path);need(st.isFile()&&!st.isSymbolicLink()&&st.size<=30*1024*1024,'ASSET_INVALID');const raw=fs.readFileSync(a.path);need(hash(raw)===a.sha256,'ASSET_HASH_CHANGED');return raw;}
export const jsonAsset=a=>JSON.parse(readAsset(a));
export function privateDir(p){need(path.isAbsolute(p),'ARTIFACT_PATH_INVALID');fs.mkdirSync(p,{recursive:true,mode:0o700});const s=fs.lstatSync(p);need(s.isDirectory()&&!s.isSymbolicLink()&&fs.realpathSync(p)===path.resolve(p)&&s.uid===process.getuid()&&(s.mode&0o777)===0o700,'ARTIFACT_PATH_UNTRUSTED');}
